import{_ as a,o,c as r,a3 as t}from"./chunks/framework.D3oaa6bG.js";const g=JSON.parse('{"title":"Categories","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage/categories.md","filePath":"guide/usage/categories.md","lastUpdated":null}'),d={name:"guide/usage/categories.md"};function s(c,e,i,p,n,l){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h1><p>Categories are used to organize <a href="./products.html">Products</a> in your store. They also define the <a href="./properties.html">Properties</a> that will be available for all related Products.</p><p>Categories can be nested. Every Category needs to be given an <code>Name</code> and a <code>URL</code>. An optional <code>Code</code> for programmatic access and a <code>image</code> can be provided.</p><h2 id="property-groups" tabindex="-1">Property groups <a class="header-anchor" href="#property-groups" aria-label="Permalink to &quot;Property groups&quot;">​</a></h2><p>By adding <a href="./properties.html">Property groups</a> to a Category you can define the &quot;Schema&quot; of related Products.</p><p>If the current Category is <code>Shirts</code>, the <code>Size</code> and <code>Color</code> Property groups can be added. As a result, every Product in the <code>Shirts</code> category will have all <code>Size</code> and <code>Color</code> properties available.</p>',6)])])}const h=a(d,[["render",s]]);export{g as __pageData,h as default};
